"""Protect source measurements and identifiers independently of the LLM prompt."""

import re


class TranslationIntegrityError(ValueError):
    """The model's response cannot safely reconstruct the source document."""


_NUMBER = r"[+\-−]?\d+(?:[.,]\d+)*(?:[eE][+\-−]?\d+)?"
_PREFIX = r"[YZEPTGMkhdcmunpfaµμ]?"
_UNIT = _PREFIX + r"(?:mol|ohm|byte|bit|Hz|Pa|eV|cd|m|s|A|K|V|W|J|N|F|H|C|Ω|g|L)(?:[23²³])?"
_UNITS = _UNIT + r"(?:\s*[*/·]\s*" + _UNIT + r")*"
STANDALONE_UNIT = re.compile(r"(?:" + _UNITS + r")\Z")
SCIENTIFIC_TOKEN = re.compile(
    r"(?<![\w.])(?:"
    + _NUMBER + r"\s*(?:" + _UNITS + r"|%)"
    + r"(?![\w²³])"
    + r"|[A-Za-z][A-Za-z0-9]*(?:_[A-Za-z0-9*]+)+"
    + r"|[A-Z][A-Z0-9]*\d[A-Z0-9]*"
    + r"|" + _NUMBER + r"(?!\w|\.\d)"
    + r")"
)


def protected_character_indices(chars):
    text = []
    owners = []
    for i, char in enumerate(chars):
        value = char.char_unicode or ""
        text.append(value)
        owners.extend([i] * len(value))
    result = set()
    for match in SCIENTIFIC_TOKEN.finditer("".join(text)):
        result.update(owners[match.start():match.end()])
    return result


def _paragraph_chars(paragraph):
    return [c.pdf_character for c in paragraph.pdf_paragraph_composition if c.pdf_character]


def merge_detached_units(paragraphs):
    """Attach a small unit XObject to the adjacent numeric value's paragraph.

    PDF generators often place a superscript/unit in a separate Form XObject.
    Treating that object as its own paragraph pins it to the old page position.
    Preserve each character's original font/XObject while sharing text layout.
    """
    removed = set()
    for unit in list(paragraphs):
        chars = _paragraph_chars(unit)
        if not 1 <= len(chars) <= 16 or any(c.vertical for c in chars):
            continue
        chars = sorted(chars, key=lambda c: c.box.x)
        text = "".join(c.char_unicode or "" for c in chars).strip()
        if not STANDALONE_UNIT.fullmatch(text):
            continue
        first = chars[0]
        height = max(c.pdf_style.font_size for c in chars)
        candidates = []
        for paragraph in paragraphs:
            if paragraph is unit or id(paragraph) in removed:
                continue
            for i, char in enumerate(_paragraph_chars(paragraph)):
                if not (char.char_unicode or "").isdigit():
                    continue
                gap = first.box.x - char.box.x2
                # The value and unit must be on the same baseline and adjacent.
                if -0.1 * height <= gap <= 1.25 * height and abs(first.box.y - char.box.y) <= .5 * height:
                    candidates.append((abs(gap), paragraph, i))
        if not candidates:
            continue
        _, paragraph, index = min(candidates, key=lambda item: item[0])
        insertion = index + 1
        paragraph.pdf_paragraph_composition[insertion:insertion] = [
            type(unit.pdf_paragraph_composition[0])(pdf_character=c) for c in chars
        ]
        removed.add(id(unit))
    return [p for p in paragraphs if id(p) not in removed]


def character_is_protected_layout(char, layouts, threshold, translate_tables):
    box = char.visual_bbox.box
    area = (box.x2 - box.x) * (box.y2 - box.y)
    if area <= 0:
        return False
    for layout in layouts:
        label = layout.class_name
        if label not in ("figure", "image", "table"):
            continue
        if label == "table" and translate_tables:
            continue
        bounds = layout.box
        overlap = max(0, min(box.x2, bounds.x2) - max(box.x, bounds.x)) * max(
            0, min(box.y2, bounds.y2) - max(box.y, bounds.y)
        )
        if overlap / area >= threshold:
            return True
    return False


def validate_model_text(text):
    if not isinstance(text, str) or not text.strip():
        raise TranslationIntegrityError("The translation response is empty.")
    if any(c == "\ufffd" or (ord(c) < 32 and c not in "\t\n\r") or 0xD800 <= ord(c) <= 0xDFFF for c in text):
        raise TranslationIntegrityError("The translation response contains invalid characters.")
